class Solution {
    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] result = new int[n][n][2];
        int[][][] degree = new int[n][n][2];
        for (int m = 0; m < n; m++)
            for (int c = 0; c < n; c++) {
                degree[m][c][0] = graph[m].length;
                degree[m][c][1] = graph[c].length;
                for (int next : graph[c]) if (next == 0) { degree[m][c][1]--; break; }
            }
        java.util.Queue<int[]> queue = new java.util.LinkedList<>();
        for (int c = 1; c < n; c++) for (int t = 0; t < 2; t++) {
            result[0][c][t] = 1; queue.offer(new int[]{0, c, t});
            result[c][c][t] = 2; queue.offer(new int[]{c, c, t});
        }
        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int m = state[0], c = state[1], t = state[2], r = result[m][c][t];
            int pt = 1 - t;
            if (pt == 0) {
                for (int pm : graph[m]) {
                    if (result[pm][c][pt] != 0) continue;
                    if (r == 1) { result[pm][c][pt] = 1; queue.offer(new int[]{pm, c, pt}); }
                    else if (--degree[pm][c][pt] == 0) { result[pm][c][pt] = 2; queue.offer(new int[]{pm, c, pt}); }
                }
            } else {
                for (int pc : graph[c]) {
                    if (pc == 0 || result[m][pc][pt] != 0) continue;
                    if (r == 2) { result[m][pc][pt] = 2; queue.offer(new int[]{m, pc, pt}); }
                    else if (--degree[m][pc][pt] == 0) { result[m][pc][pt] = 1; queue.offer(new int[]{m, pc, pt}); }
                }
            }
        }
        return result[1][2][0];
    }
}
